filldraw((0,0)--(-1,0)..dir(135)..(0,1)--(0,0)--cycle,gray,linewidth(2));
draw((0,1)..dir(45)..(1,0),dashed);

draw((1-7/25,24/25)--(1+17/25,31/25)..(1-7/25,24/25)+dir(-30)..(1,0)--(1-7/25,24/25)--cycle,dashed);

